const DOMAIN='solix_live';
class SolixLivePanel extends HTMLElement {
 set hass(value){this._hass=value;if(this._ready)this.refresh();}
 set panel(value){this._panel=value;}
 set narrow(value){this._narrow=value;}
 connectedCallback(){if(this._ready)return;this._ready=true;this.attachShadow({mode:'open'});
 this.shadowRoot.innerHTML=`<style>
*{box-sizing:border-box}:host{display:block;background:#071624;color:#eefaff;font:15px system-ui,-apple-system,sans-serif}.wrap{width:100%;max-width:1450px;margin:auto;padding:12px}.scene{position:relative;aspect-ratio:1648/928;border-radius:20px;overflow:hidden;background:#10243b;box-shadow:0 20px 70px #0008}.scene svg{display:block;width:100%;height:100%}.controls{margin-top:12px;padding:15px;border:1px solid #31506a;border-radius:16px;background:#10283a;display:flex;flex-wrap:wrap;gap:12px;align-items:center}.controls button{background:#1c455c;border:1px solid #54839a;border-radius:9px;color:white;padding:10px 15px;font:inherit}.controls label{display:flex;gap:6px;align-items:center}.controls input{accent-color:#3de9c9}.note{font-size:12px;color:#a6c0d0;margin-top:10px}.clickable{cursor:pointer}.clickable:hover .card{stroke:#fff;stroke-width:3} .tiny{font-size:23px;fill:#c6e4f1}.big{font-size:40px;font-weight:750;fill:white}.card{fill:#071d31;fill-opacity:.91;stroke:#68b6d0;stroke-width:2}.cable{fill:none;stroke:#122b37;stroke-width:15;stroke-linejoin:round;stroke-linecap:round}.cableInner{fill:none;stroke:#277b84;stroke-width:6;stroke-linejoin:round;stroke-linecap:round}.orangeInner{stroke:#a86b2c}.pulse{fill:none;stroke-width:9;stroke-linecap:round;stroke-dasharray:24 220;filter:url(#glow)}.pulseCore{fill:none;stroke-width:4;stroke-linecap:round;stroke-dasharray:24 220}.badge{fill:#062638;fill-opacity:.91;stroke:#4c96a2;stroke-width:2} @media(max-width:700px){.wrap{padding:6px}.scene{border-radius:12px}.controls{font-size:13px;gap:8px}.controls button{padding:8px}.note{padding:0 5px}}
</style><div class="wrap"><div class="scene"><svg aria-label="SOLIX Energiefluss auf freigegebenem Hausmotiv" id="view" viewbox="0 0 1648 928" xmlns="http://www.w3.org/2000/svg"><defs><filter height="500%" id="glow" width="300%" x="-100%" y="-200%"><fegaussianblur result="b" stddeviation="7"></fegaussianblur><femerge><femergenode in="b"></femergenode><femergenode in="SourceGraphic"></femergenode></femerge></filter><lineargradient id="battery" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#39464e"></stop><stop offset=".55" stop-color="#17262d"></stop><stop offset="1" stop-color="#0c151b"></stop></lineargradient><lineargradient id="roofline" x1="0" x2="1"><stop stop-color="#38e5dd"></stop><stop offset="1" stop-color="#76fff0"></stop></lineargradient></defs>
<image height="928" href="data:image/png;base64," preserveaspectratio="xMidYMid meet" width="1648" x="0" y="0"/>
<!-- cables and their animation share identical SVG paths -->
<path class="cable" d="M 718 278 L 745 318 Q 766 340 766 370 L 766 624" id="pv"></path><use class="cableInner" href="#pv"></use>
<path class="cable" d="M 830 693 L 1030 693" id="trunk"></path><use class="cableInner orangeInner" href="#trunk"></use>
<path class="cable" d="M 1030 693 L 1063 693 Q 1090 693 1090 666 L 1090 508 Q 1090 478 1120 478 L 1210 478" id="house"></path><use class="cableInner orangeInner" href="#house"></use>
<path class="cable" d="M 1030 693 L 1210 693" id="feed"></path><use class="cableInner orangeInner" href="#feed"></use>
<!-- single physical-looking solarbank right of downpipe, flush to white wall -->
<ellipse cx="762" cy="748" fill="#07121c" opacity=".5" rx="91" ry="18"></ellipse>
<rect fill="url(#battery)" height="125" rx="16" stroke="#758b91" stroke-width="4" width="166" x="678" y="622"></rect><rect fill="none" height="105" opacity=".2" rx="11" stroke="#a3b5b9" width="148" x="687" y="634"></rect><path d="M 705 716 H 817" filter="url(#glow)" stroke="#35dfcc" stroke-width="6"></path><text fill="white" font-size="25" font-weight="700" letter-spacing="3" text-anchor="middle" x="761" y="670">ANKER</text><text fill="white" font-size="22" letter-spacing="5" text-anchor="middle" x="761" y="696">SOLIX</text>
<!-- cards overlay house -->
<g class="clickable" id="solarCard"><rect class="card" height="120" rx="24" stroke="#4af0e0" width="335" x="100" y="145"></rect><text class="tiny" x="124" y="188">☀ Solarleistung · 8 Panels</text><text class="big" id="pvValue" x="124" y="240">1.200 W</text></g>
<g class="clickable" id="houseCard"><rect class="card" height="135" rx="24" width="390" x="1210" y="413"></rect><text class="tiny" x="1240" y="460">⌂ Hausverbrauch</text><text class="big" id="houseValue" x="1240" y="517">400 W</text></g>
<g class="clickable" id="feedCard"><rect class="card" height="135" rx="24" stroke="#f3a948" width="390" x="1210" y="631"></rect><text class="tiny" x="1240" y="680">↗ Hauseinspeisung</text><text class="big" id="feedValue" x="1240" y="738">800 W</text></g>
<g class="clickable" id="batteryCard"><rect class="badge" height="73" rx="21" width="260" x="635" y="765"></rect><text fill="#6cf4ab" font-size="22" font-weight="700" x="654" y="794">⚡ Laden</text><text fill="#e4f5fc" font-size="22" x="654" y="822">Beide Systeme · 83 %</text></g>
<g><rect class="badge" height="71" rx="20" width="365" x="28" y="25"></rect><text fill="white" font-size="25" font-weight="700" x="52" y="56">SOLIX Energy Center</text><text fill="#c5e1ec" font-size="18" x="52" y="82">2 Systeme · 8 Solarpanels</text></g>
<path d="M 718 278 L 745 318 Q 766 340 766 370 L 766 624" fill="none" id="motion-solar" pointer-events="none" stroke="none"></path><g id="packet-solar-0" pointer-events="none"><circle fill="#4dffeb" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#4dffeb" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-solar-1" pointer-events="none"><circle fill="#4dffeb" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#4dffeb" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-solar-2" pointer-events="none"><circle fill="#4dffeb" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#4dffeb" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><path d="M 830 693 L 1030 693 L 1063 693 Q 1090 693 1090 666 L 1090 508 Q 1090 478 1120 478 L 1210 478" fill="none" id="motion-home" pointer-events="none" stroke="none"></path><g id="packet-home-0" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-home-1" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-home-2" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><path d="M 830 693 L 1030 693 L 1210 693" fill="none" id="motion-export" pointer-events="none" stroke="none"></path><g id="packet-export-0" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-export-1" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-export-2" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g><g id="packet-export-3" pointer-events="none"><circle fill="#ffb13e" filter="url(#glow)" opacity=".42" r="14"></circle><circle fill="#ffb13e" r="7"></circle><circle fill="#ffffff" r="3.5"></circle></g></svg></div><div class="note" id="status" role="status"></div>
<section class="details" aria-label="SOLIX Systemdetails">
<h2>Systemdetails · Batterieüberwachung</h2><div class="detail-grid" id="deviceDetails"></div>
<details><summary>PV-Eingänge / MPPT</summary><div class="detail-grid" id="mpptDetails"></div></details>
<details><summary>Smart-Plugs</summary><div class="detail-grid" id="plugDetails"></div></details>
</section></div>`;
 this.$=id=>this.shadowRoot.getElementById(id);
 this._tracks=[{key:'solar',speed:130,count:3,field:'pv'},{key:'home',speed:125,count:3,field:'home'},{key:'export',speed:145,count:4,field:'export'}].map(r=>({...r,path:this.$('motion-'+r.key),dots:Array.from({length:r.count},(_,i)=>this.$('packet-'+r.key+'-'+i))}));
 this._clock=0;this._last=performance.now();this._tick=this._tick.bind(this);
 for(const [id,kind] of [['solarCard','pv'],['batteryCard','battery'],['houseCard','home'],['feedCard','export']]){const node=this.$(id);if(node){node.style.cursor='pointer';node.addEventListener('click',()=>this.openDetails(kind));}}
 const style=document.createElement('style');style.textContent='.details{margin-top:16px;padding:16px;border:1px solid #31506a;border-radius:16px;background:#10283a}.details h2{margin:0 0 14px;font-size:19px}.detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:10px 0}.detail-tile{background:#071d31;border:1px solid #31506a;border-radius:12px;padding:12px;min-width:0}.detail-tile strong{display:block;margin-bottom:8px}.detail-tile p{margin:4px 0;color:#c6e4f1}.detail-tile small{color:#a6c0d0}.details details{margin-top:12px}.details summary{cursor:pointer;padding:12px;background:#17364c;border-radius:10px}@media(max-width:650px){.detail-grid{grid-template-columns:1fr}}';this.shadowRoot.append(style);
 this.refresh();this._raf=requestAnimationFrame(this._tick);
 }
 disconnectedCallback(){if(this._raf)cancelAnimationFrame(this._raf);this._raf=null;}
 _num(id){const s=this._hass?.states?.[id]?.state;if(s==null||['unknown','unavailable','none',''].includes(String(s).toLowerCase()))return null;const n=Number(s);return Number.isFinite(n)?n:null;}
 _fmt(v){return v===null?'–':Math.round(v).toLocaleString('de-DE')+' W';}
 refresh(){if(!this._ready||!this._hass)return;const pre='sensor.solix_live_';
 const pv=this._num(pre+'solarleistung'),home=this._num(pre+'hausverbrauch'),exp=this._num(pre+'hauseinspeisung'),out=this._num(pre+'ausgangsleistung'),soc=this._num(pre+'ladestand');
 const state=this._hass.states[pre+'betriebszustand']?.state||'Unbekannt';
 this._values={pv,home,export:exp};
 for(const [id,v] of [['pvValue',pv],['houseValue',home],['feedValue',exp]]){const el=this.$(id);if(el)el.textContent=this._fmt(v);}
 const battery=this.$('batteryCard');if(battery){const texts=battery.querySelectorAll('text');const b=[...texts];if(b.length>1){b[0].textContent='⚡ '+state;b[1].textContent='Beide Systeme · '+(soc===null?'–':Math.round(soc)+' %');}}
 this.renderDetails();
 const status=this.$('status');if(status)status.textContent=(pv===null||out===null||home===null)?'Einzelne Live-Sensoren sind nicht verfügbar. Bitte SOLIX Live unter Geräte & Dienste konfigurieren.':'Live-Daten aus Home Assistant · Solarbank-Ausgang '+this._fmt(out);
 }
 renderDetails(){
 const attrs=this._hass?.states?.['sensor.solix_live_systemdetails']?.attributes||{};
 const fmt=(value,unit)=>value===null||value===undefined||!Number.isFinite(Number(value))?'Nicht verfügbar':Number(value).toLocaleString('de-DE',{maximumFractionDigits:1})+' '+unit;
 const escape=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const devices=this.$('deviceDetails');
 if(devices)devices.innerHTML=(attrs.devices||[]).map(d=>'<div class="detail-tile"><strong>'+escape(d.name)+'</strong><p>🌡 Temperatur: '+fmt(d.temp,'°C')+'</p><p>🔋 Ladestand: '+fmt(d.soc,'%')+'</p><p>⚡ Lade-/Entladeleistung: '+fmt(d.power,'W')+'</p><small>'+(d.heated?'Mit Akkuheizung':'Ohne Akkuheizung')+'</small></div>').join('')||'<p>Gerätewerte bitte in den Integrationsoptionen zuordnen.</p>';
 const mppts=this.$('mpptDetails');
 if(mppts)mppts.innerHTML=(attrs.mppts||[]).map(d=>'<div class="detail-tile"><strong>System '+escape(d.system)+' · MPPT '+escape(d.index)+'</strong><p>'+fmt(d.power,'W')+'</p></div>').join('')||'<p>MPPT-Sensoren noch nicht konfiguriert.</p>';
 const plugs=this.$('plugDetails');
 if(plugs)plugs.innerHTML=(attrs.plugs||[]).map(d=>'<div class="detail-tile"><strong>'+escape(d.name)+'</strong><p>'+fmt(d.power,'W')+'</p></div>').join('')||'<p>Keine Smart-Plugs ausgewählt.</p>';
 }
 _tick(now){const dt=Math.max(0,Math.min(.05,(now-this._last)/1000));this._last=now;this._clock+=dt;
 for(const r of this._tracks){const val=this._values?.[r.field];const enabled=val!==null&&val>0;const len=r.path.getTotalLength();const speed=r.speed*(val==null?1:Math.min(1.8,Math.max(.5,val/800)));
 for(let i=0;i<r.count;i++){const dot=r.dots[i],spacing=len/r.count,dist=(this._clock*speed-i*spacing)%(len+spacing);if(!enabled||dist<0||dist>len){dot.style.display='none';continue;}dot.style.display='';const pt=r.path.getPointAtLength(dist);dot.setAttribute('transform',`translate(${pt.x} ${pt.y})`);}}
 this._raf=requestAnimationFrame(this._tick);
 }
 openDetails(kind){const pre='sensor.solix_live_';const id={pv:pre+'solarleistung',battery:pre+'ladestand',home:pre+'hausverbrauch',export:pre+'hauseinspeisung'}[kind];if(!id)return;this.dispatchEvent(new CustomEvent('hass-more-info',{bubbles:true,composed:true,detail:{entityId:id}}));}
}
if(!customElements.get('solix-live-panel'))customElements.define('solix-live-panel',SolixLivePanel);
